Address address = new Address("서울", "강남대로", "12345");
member1.setHomeAddress(address);

Address copy = new Address(address.getCity(),
                           address.getStreet(),
                           address.getZipcode());
member2.setHomeAddress(copy);      // 다른 객체

@Embeddable
public class Address {

    private String city;
    private String street;
    private String zipcode;

    protected Address() {}      // JPA 용. protected 로 막는다.

    public Address(String city, String street, String zipcode) {
        this.city = city;
        this.street = street;
        this.zipcode = zipcode;
    }

    public String getCity()    { return city; }
    public String getStreet()  { return street; }
    public String getZipcode() { return zipcode; }

    // setter 가 없다
}

Address old = member.getHomeAddress();

member.setHomeAddress(
    new Address("부산", old.getStreet(), old.getZipcode())
);

